    if (i == a.size()) { all.push_back(cur); return; }   // leaf
    cur.push_back(a[i]);   // PICK
    gen(i + 1, a, cur, all);
    cur.pop_back();        // UNDO — backtracking hygiene
    gen(i + 1, a, cur, all);                              // NOT-PICK
}

