def gen(i, a, cur, all_):
    if i == len(a):
        all_.append(cur[:]); return   # leaf - COPY state out
    cur.append(a[i]); gen(i+1, a, cur, all_)   # PICK
    cur.pop()                                    # UNDO - backtrack
    gen(i+1, a, cur, all_)                       # NOT-PICK

