// EXISTS (short-circuit OR-chain)
bool exists(int i, int sum, int k, vector<int>& a){
    if (i == a.size()) return sum == k;
    return exists(i+1, sum + a[i], k, a) || exists(i+1, sum, k, a);
}
// COUNT (functional addition)
int count(int i, int sum, int k, vector<int>& a){
    if (i == a.size()) return sum == k;
    return count(i+1, sum+a[i], k, a) + count(i+1, sum, k, a);
}

