void comb(int i, int rem, vector<int>& c, vector<int>& cur, vector<vector<int>>& out){
    if (i == c.size()) return;
    if (rem == 0) { out.push_back(cur); return; }
    if (c[i] <= rem) {
        cur.push_back(c[i]);
        comb(i, rem - c[i], c, cur, out);   // SAME i: reuse allowed
        cur.pop_back();
    }
    comb(i + 1, rem, c, cur, out);           // move past this coin
}
